def safe_join(base, user_path):
    if not base or not user_path:
        raise ValueError("Base and user path must be non-empty strings")
    if user_path.startswith('/'):
        raise ValueError("User path must not be an absolute path")
    if '..' in user_path.split('/'):
        raise ValueError("User path must not contain '..' to escape the base directory")
    if user_path == '.' or user_path == '':
        return base
    components = user_path.split('/')
    result = base
    for component in components:
        if component == '.':
            continue
        if component == '..':
            if result == base:
                continue
            result = '/'.join(result.split('/')[:-1])
        else:
            result = '/'.join([result, component])
    if result == base:
        return base
    if result.startswith(base + '/'):
        return result
    else:
        raise ValueError("User path must be within the base directory")
