def evaluate_rpn(tokens):
    stack = []
    for token in tokens:
        if token.isdigit() or (token[0] == '-' and token[1:].isdigit()):
            stack.append(int(token))
        elif token in '+-*/':
            if len(stack) < 2:
                raise ValueError('Invalid expression')
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            elif token == '/':
                if b == 0:
                    raise ValueError('Division by zero')
                stack.append(int(a / b))
        else:
            raise ValueError('Invalid token')
    if len(stack) != 1:
        raise ValueError('Invalid expression')
    return stack[0]

def sliding_window_max(nums, k):
    n = len(nums)
    if k <= 0 or k > n:
        raise ValueError("k must be positive and less than or equal to the length of nums")
    deque = []
    res = []
    for i in range(n):
        while deque and nums[deque[-1]] <= nums[i]:
            deque.pop()
        deque.append(i)
        if deque[0] == i - k:
            deque.pop(0)
        if i >= k - 1:
            res.append(nums[deque[0]])
    return res
